--- a/servers/rendering/rendering_device.h
+++ b/servers/rendering/rendering_device.h
@@ -1493,6 +1493,17 @@
 	void _release_transfer_worker(TransferWorker *p_transfer_worker);
 	void _end_transfer_worker(TransferWorker *p_transfer_worker);
 	void _submit_transfer_worker(TransferWorker *p_transfer_worker, VectorView<RDD::SemaphoreID> p_signal_semaphores = VectorView<RDD::SemaphoreID>());
+
+	static constexpr uint32_t FENCE_WAIT_MAX_RETRIES = 60;
+
+	Error _fence_wait_with_retry(RDD::FenceID p_fence, const char *p_site);
+
 	void _wait_for_transfer_worker(TransferWorker *p_transfer_worker);
 	void _flush_barriers_for_transfer_worker(TransferWorker *p_transfer_worker);
 	void _check_transfer_worker_operation(uint32_t p_transfer_worker_index, uint64_t p_transfer_worker_operation);
--- a/servers/rendering/rendering_device.cpp
+++ b/servers/rendering/rendering_device.cpp
@@ -6002,11 +6002,39 @@
 	{
 		MutexLock lock(p_transfer_worker->operations_mutex);
 		p_transfer_worker->operations_submitted = p_transfer_worker->operations_counter;
+	}
+}
+
+Error RenderingDevice::_fence_wait_with_retry(RDD::FenceID p_fence, const char *p_site) {
+	Error err = ERR_TIMEOUT;
+	for (uint32_t i = 0; i < FENCE_WAIT_MAX_RETRIES && err == ERR_TIMEOUT; i++) {
+		err = driver->fence_wait(p_fence);
+		if (err == ERR_TIMEOUT && i > 0) {
+			WARN_PRINT_ONCE(vformat(
+					"%s: fence_wait timed out, retrying (%d/%d). "
+					"This may indicate a slow GPU op or driver hang.",
+					p_site, i + 1, FENCE_WAIT_MAX_RETRIES));
+		}
+	}
+	if (err != OK) {
+		ERR_PRINT(vformat(
+				"%s: fence_wait failed after %d retries (error=%d). "
+				"Skipping subsequent pool reset to avoid state corruption.",
+				p_site, FENCE_WAIT_MAX_RETRIES, err));
 	}
+	return err;
 }

 void RenderingDevice::_wait_for_transfer_worker(TransferWorker *p_transfer_worker) {
-	driver->fence_wait(p_transfer_worker->command_fence);
+	if (_fence_wait_with_retry(p_transfer_worker->command_fence, "transfer_worker") != OK) {
+		// Do NOT reset the pool — GPU still owns these resources.
+		return;
+	}
 	driver->command_pool_reset(p_transfer_worker->command_pool);
 	p_transfer_worker->staging_buffer_size_in_use = 0;
 	p_transfer_worker->submitted = false;
@@ -6836,7 +6864,11 @@

 	if (frames[p_frame].fence_signaled) {
 		GodotProfileZoneGroupedFirst(_profile_zone, "driver->fence_wait");
-		driver->fence_wait(frames[p_frame].fence);
+		_fence_wait_with_retry(frames[p_frame].fence, "frame_fence");
 		frames[p_frame].fence_signaled = false;

 		// Flush any pending requests for asynchronous buffer downloads.
```
</details>

