+static void _gso_fence_wait_until_signaled(RenderingDeviceDriver *p_driver, RDD::FenceID p_fence, const char *p_what) {
+	Error err = p_driver->fence_wait(p_fence);
+	if (likely(err == OK)) {
+		return;
+	}
+	const uint64_t start_ms = OS::get_singleton()->get_ticks_msec();
+	uint32_t attempts = 1;
+	while (err != OK) {
+		const uint64_t waited_ms = OS::get_singleton()->get_ticks_msec() - start_ms;
+		ERR_PRINT(vformat("RenderingDevice: %s fence_wait not signaled after %d attempt(s), ~%d ms total (err %d). Retrying; if this repeats indefinitely the GPU is wedged.", p_what, attempts, (int64_t)waited_ms, (int64_t)err));
+		err = p_driver->fence_wait(p_fence);
+		attempts++;
+	}
+	ERR_PRINT(vformat("RenderingDevice: %s fence_wait recovered after %d attempt(s), ~%d ms total.", p_what, attempts, (int64_t)(OS::get_singleton()->get_ticks_msec() - start_ms)));
+}
+
 void RenderingDevice::_wait_for_transfer_worker(TransferWorker *p_transfer_worker) {
-	driver->fence_wait(p_transfer_worker->command_fence);
+	_gso_fence_wait_until_signaled(driver, p_transfer_worker->command_fence, "transfer worker");
 	driver->command_pool_reset(p_transfer_worker->command_pool);
 	p_transfer_worker->staging_buffer_size_in_use = 0;
 	p_transfer_worker->submitted = false;
@@ -8216,7 +8232,7 @@ void RenderingDevice::_stall_for_frame(uint32_t p_frame) {

